// catalogue/agenda-bundle/: the Agenda's module graph and its stylesheets, bundled, so the page opens in a handful of
// requests instead of fifty (Kenny, 2026-10-19: "drastically lower"; measured the same morning: 56 requests, about 36 of
// them the page's own modules, 7 stylesheets, 2 fonts, 4 JSON files).
//
//   agenda.js      esbuild's bundle of the six module scripts catalogue/agenda.html used to list, in that order.
//                  NOT split: every import() in the graph (the components js/auto.js attaches, demos.js,
//                  devtools.js, ...) resolves inside this one file, so each module exists once, with one set of module
//                  state, and the page never asks for a second copy of a module by its own address. Splitting was tried
//                  and refused: the sharing between the entry and the lazy modules cut the graph into 180 chunks, 18 of
//                  them on the first view, for a bundle that is no smaller.
//   agenda.css     the library sheets and the catalogue's, concatenated in their old order. The theme registers stay
//                  linked on their own (js/lazy-register.js finds a register by its href, and the Agenda writes the one
//                  of the stored theme itself); they only fill the layers kp.register and kp.signature, so where they
//                  sit relative to the catalogue's own sheets decides nothing.
//
// import.meta.url is rewritten per source file to the address of that source file, so every
// `new URL('./verdicts.json', import.meta.url)` still reads the file beside the module it is written in, not one beside
// the bundle.
//
//   node gates/generate-agenda-bundle.mjs           write catalogue/agenda-bundle/
//   node gates/generate-agenda-bundle.mjs --check   exit 1 when it is stale (no browser)
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import process from 'node:process';
import * as esbuild from 'esbuild';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
export const OUT = join(ROOT, 'catalogue/agenda-bundle');

/** The module scripts of catalogue/agenda.html, in the order the page ran them. */
export const SCRIPTS = [
    'js/auto.js',
    'catalogue/catalogue-shell.js',
    'catalogue/agenda.js',
    'catalogue/play.js',
    'catalogue/checklist.js',
    'catalogue/shortcuts.js',
];

/** The stylesheets, in the order the page linked them (the registers aside, see the head). */
export const STYLES = [
    'css/fonts.css',
    'css/themes.css',
    'css/components.css',
    'css/layout.css',
    'css/utilities.css',
    'catalogue/catalogue.css',
    'catalogue/agenda.css',
    'research/_review/rv-progress.css',
    'research/_review/flow.css',
];

/** Rewrites import.meta.url to the address of the file it was written in. */
const keepMetaUrl = {
    name: 'keep-meta-url',
    /** @param {esbuild.PluginBuild} build */
    setup(build) {
        build.onLoad({ filter: /\.js$/ }, (args) => {
            if (args.path.includes(`${sep}node_modules${sep}`)) return undefined;
            const source = readFileSync(args.path, 'utf8');
            if (!source.includes('import.meta.url')) return undefined;
            const there = relative(OUT, args.path).split(sep).join('/');
            return { contents: source.replaceAll('import.meta.url', `new URL(${JSON.stringify(there)}, import.meta.url).href`), loader: 'js' };
        });
    },
};

/** url(...) in a sheet, re-addressed from the sheet's folder to the bundle's. */
function readdress(/** @type {string} */ css, /** @type {string} */ file) {
    return css.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/g, (whole, quote, address) => {
        if (/^(data:|https?:|\/|#)/.test(address)) return whole;
        const target = resolve(dirname(join(ROOT, file)), address);
        return `url(${quote}${relative(OUT, target).split(sep).join('/')}${quote})`;
    });
}

/** The sheet: every stylesheet in turn, under a line naming it. */
function sheet() {
    const head = `/* catalogue/agenda-bundle/agenda.css. Generated by gates/generate-agenda-bundle.mjs; do not edit by hand.\n   ${STYLES.join(', ')}, concatenated in order. */\n`;
    return (
        head +
        STYLES.map(
            (file) => `\n/* ---- ${file} ---- */\n${readdress(readFileSync(join(ROOT, file), 'utf8').replace(/^﻿/, ''), file).trimEnd()}\n`,
        ).join('')
    );
}

/** Every file the bundle is made of, as [path relative to the bundle folder, text]. */
export async function build() {
    const entry = SCRIPTS.map((file) => `import '${join(ROOT, file)}';`).join('\n');
    const result = await esbuild.build({
        stdin: { contents: entry, resolveDir: ROOT, sourcefile: 'agenda-entry.js', loader: 'js' },
        outdir: OUT,
        bundle: true,
        // whitespace only: nothing is renamed or rewritten, so the code that runs is the code that was written
        minifyWhitespace: true,
        format: 'esm',
        target: 'es2022',
        write: false,
        legalComments: 'none',
        // package.json lists only js/auto.js as having side effects; the catalogue scripts run on import, so esbuild must not drop them
        ignoreAnnotations: true,
        entryNames: 'agenda',
        plugins: [keepMetaUrl],
        logLevel: 'silent',
    });
    /** @type {[string, string][]} */
    const files = result.outputFiles.map((f) => [relative(OUT, f.path).split(sep).join('/'), f.text]);
    files.push(['agenda.css', sheet()]);
    return files.sort((a, b) => (a[0] < b[0] ? -1 : 1));
}

/** The files in the bundle folder now. */
function onDisk() {
    return existsSync(OUT) ? readdirSync(OUT).sort() : [];
}

async function main() {
    const files = await build();
    if (process.argv.includes('--check')) {
        const names = files.map(([name]) => name);
        const there = onDisk();
        const stale = names.join() !== there.join() || files.some(([name, text]) => readFileSync(join(OUT, name), 'utf8') !== text);
        if (stale) {
            console.error('catalogue/agenda-bundle/ is stale; run node gates/generate-agenda-bundle.mjs and commit it with the change');
            process.exit(1);
        }
        console.log(`agenda bundle: ${files.length} files, current.`);
        return;
    }
    rmSync(OUT, { recursive: true, force: true });
    mkdirSync(OUT, { recursive: true });
    for (const [name, text] of files) writeFileSync(join(OUT, name), text);
    console.log(`catalogue/agenda-bundle/: ${files.length} files, ${Math.round(files.reduce((n, [, t]) => n + t.length, 0) / 1024)} KB.`);
}

if (import.meta.url === `file://${process.argv[1]}`) await main();
